real_t algorithm_histogram(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
#if defined(__riscv_vector)
        {
            Index_type i = 0;
            for (; i + 4 <= 256; i += 4) {
                asm volatile(
                    "fmv.d.x ft0, zero\n\t"
                    "fsd ft0, 0(%0)\n\t"
                    "fsd ft0, 8(%0)\n\t"
                    "fsd ft0, 16(%0)\n\t"
                    "fsd ft0, 24(%0)\n\t"
                    :
                    : "r"(&x[i])
                    : "memory", "ft0");
            }
            for (; i < 256; ++i) x[i] = 0.0;
        }
#else
        for (Index_type i = 0; i < 256; ++i) x[i] = 0.0;
#endif

        {
            Index_type i = 0;
            for (; i + 4 <= LEN_1D; i += 4) {
                x[idx_list[i + 0]] += 1.0;
                x[idx_list[i + 1]] += 1.0;
                x[idx_list[i + 2]] += 1.0;
                x[idx_list[i + 3]] += 1.0;
            }
            for (; i < LEN_1D; ++i) {
                x[idx_list[i]] += 1.0;
            }
        }

        dummy(x, NULL, NULL, NULL, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
