real_t algorithm_reduce_sum(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t acc = 0.0;

#if defined(__riscv_vector) && defined(__has_include)
# if __has_include(<riscv_vector.h>)
#  include <riscv_vector.h>
# endif
#endif

#if defined(__riscv_vector) && defined(__has_include) && __has_include(<riscv_vector.h>)
    for (int nl = 0; nl < iterations; nl++) {
        real_t s = 0.0;
        Index_type i = 0;

        #if __SIZEOF_DOUBLE__ == __SIZEOF_POINTER__
        while (i < LEN_1D) {
            size_t vl = __riscv_vsetvl_e64m1((size_t)(LEN_1D - i));
            vfloat64m1_t vx = __riscv_vle64_v_f64m1((const double *)(x + i), vl);
            vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, vl);
            vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(vx, vzero, vl);
            s += __riscv_vfmv_f_s_f64m1_f64(vred);
            i += (Index_type)vl;
        }
        #else
        while (i < LEN_1D) {
            size_t vl = __riscv_vsetvl_e32m1((size_t)(LEN_1D - i));
            vfloat32m1_t vx = __riscv_vle32_v_f32m1((const float *)(x + i), vl);
            vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(0.0f, vl);
            vfloat32m1_t vred = __riscv_vfredusum_vs_f32m1_f32m1(vx, vzero, vl);
            s += (real_t)__riscv_vfmv_f_s_f32m1_f32(vred);
            i += (Index_type)vl;
        }
        #endif

        acc += s;
        dummy(x, NULL, NULL, NULL, NULL, s);
    }
#else
    for (int nl = 0; nl < iterations; nl++) {
        real_t s = 0.0;
        for (Index_type i = 0; i < LEN_1D; ++i) s += x[i];
        acc += s;
        dummy(x, NULL, NULL, NULL, NULL, s);
    }
#endif

    y[0] = acc;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

real_t algorithm_scan(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
