        Index_type i = 0;

        const real_t * __restrict px = x;
        real_t * __restrict py = y;

#if defined(__riscv)
        for (; i + 7 < LEN_1D; i += 8) {
            real_t s0 = scan_var;
            real_t x0 = px[i + 0];
            real_t s1 = s0 + x0;
            real_t x1 = px[i + 1];
            real_t s2 = s1 + x1;
            real_t x2 = px[i + 2];
            real_t s3 = s2 + x2;
            real_t x3 = px[i + 3];
            real_t s4 = s3 + x3;
            real_t x4 = px[i + 4];
            real_t s5 = s4 + x4;
            real_t x5 = px[i + 5];
            real_t s6 = s5 + x5;
            real_t x6 = px[i + 6];
            real_t s7 = s6 + x6;
            real_t x7 = px[i + 7];

            py[i + 0] = s0;
            py[i + 1] = s1;
            py[i + 2] = s2;
            py[i + 3] = s3;
            py[i + 4] = s4;
            py[i + 5] = s5;
            py[i + 6] = s6;
            py[i + 7] = s7;

            scan_var = s7 + x7;
        }
#endif

        for (; i < LEN_1D; ++i) {
            py[i] = scan_var;
            scan_var += px[i];
        }

        dummy(x, y, NULL, NULL, NULL, scan_var);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

real_t apps_del_dot_vec_2d(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    const real_t half = 0.5f, ptiny = 1.0e-20f;

    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            real_t x1  = apps_x1[i];
            real_t x2  = apps_x2[i];
            real_t x3  = apps_x3[i];
            real_t x4  = apps_x4[i];
            real_t y1  = apps_y1[i];
            real_t y2  = apps_y2[i];
            real_t y3  = apps_y3[i];
            real_t y4  = apps_y4[i];
            real_t fx1 = apps_fx1[i];
            real_t fx2 = apps_fx2[i];
            real_t fx3 = apps_fx3[i];
            real_t fx4 = apps_fx4[i];
            real_t fy1 = apps_fy1[i];
            real_t fy2 = apps_fy2[i];
            real_t fy3 = apps_fy3[i];
            real_t fy4 = apps_fy4[i];

            real_t xi  = half * ( x1  + x2  - x3  - x4  );
            real_t xj  = half * ( x2  + x3  - x4  - x1  );
            real_t yi  = half * ( y1  + y2  - y3  - y4  );
            real_t yj  = half * ( y2  + y3  - y4  - y1  );
            real_t fxi = half * ( fx1 + fx2 - fx3 - fx4 );
            real_t fxj = half * ( fx2 + fx3 - fx4 - fx1 );
            real_t fyi = half * ( fy1 + fy2 - fy3 - fy4 );
            real_t fyj = half * ( fy2 + fy3 - fy4 - fy1 );
            real_t rarea = 1.0f / ( xi * yj - xj * yi + ptiny );
            real_t dfxdx = rarea * ( fxi * yj - fxj * yi );
            real_t dfydy = rarea * ( fyj * xi - fyi * xj );
            real_t affine = ( fy1 + fy2 + fy3 + fy4 ) / ( y1 + y2 + y3 + y4 );

            apps_div[i] = dfxdx + dfydy + affine;
        }
        dummy(apps_div, NULL, NULL, NULL, NULL, ptiny);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

real_t apps_energy(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    const real_t rho0 = 1.0f, e_cut = 1.0e-7f, emin = -1.0e15f;
    const int n = APPS_N1D;
    const int outer = iterations / 8 + 1;

    for (int nl = 0; nl < outer; nl++) {
        for (Index_type i = 0; i < n; ++i) {
            apps_e_new[i] = apps_e_old[i]
                          - 0.5f * apps_delvc[i] * (apps_p_old[i] + apps_q_old[i])
                          + 0.5f * apps_work[i];
        }

        for (Index_type i = 0; i < n; ++i) {
            if (apps_delvc[i] > 0.0f) {
                apps_q_new[i] = 0.0f;
            } else {
                real_t vhalf = 1.0f / (1.0f + apps_compHalfStep[i]);
                real_t ssc = (apps_pbvc[i] * apps_e_new[i] +
                              vhalf * vhalf * apps_bvc[i] * apps_pHalfStep[i]) / rho0;
                if (ssc <= 1.111111e-36f) ssc = 3.333333e-18f;
                else                      ssc = sqrtf(ssc);
                apps_q_new[i] = ssc * apps_ql_old[i] + apps_qq_old[i];
            }
        }

        for (Index_type i = 0; i < n; ++i) {
            apps_e_new[i] += 0.5f * apps_delvc[i] *
                             (3.0f * (apps_p_old[i] + apps_q_old[i]) -
                              4.0f * (apps_pHalfStep[i] + apps_q_new[i]));
        }

        for (Index_type i = 0; i < n; ++i) {
            apps_e_new[i] += 0.5f * apps_work[i];
            if (ABS(apps_e_new[i]) < e_cut) apps_e_new[i] = 0.0f;
            if (apps_e_new[i] < emin)       apps_e_new[i] = emin;
        }

        dummy(apps_e_new, apps_q_new, NULL, NULL, NULL, e_cut);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

real_t apps_fir(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    const Index_type coefflen = APPS_COEFFLEN;

    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
        const real_t *coeff = apps_coeff;
        const real_t *in = apps_in;
        real_t *out = apps_out;

        for (Index_type i = 0; i < APPS_N1D; ++i) {
            real_t s = 0.0f;
            for (Index_type j = 0; j < coefflen; ++j) {
                s += coeff[j] * in[i + j];
            }
            out[i] = s;
        }

        dummy(apps_out, NULL, NULL, NULL, NULL, 0.0f);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

real_t apps_ltimes_noview(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type num_d = LTIMES_NUM_D, num_m = LTIMES_NUM_M;
    Index_type num_g = LTIMES_NUM_G, num_z = LTIMES_NUM_Z;

    for (int nl = 0; nl < iterations; nl++) {
        for (Index_type z = 0; z < num_z; ++z) {
            const Index_type z_mg = z * num_m * num_g;
            const Index_type z_dg = z * num_d * num_g;

            for (Index_type g = 0; g < num_g; ++g) {
                const Index_type phi_base = g * num_m + z_mg;
                const Index_type psi_base = g * num_d + z_dg;

                Index_type m = 0;

                for (; m + 3 < num_m; m += 4) {
                    const Index_type ell0 = (m + 0) * num_d;
                    const Index_type ell1 = (m + 1) * num_d;
                    const Index_type ell2 = (m + 2) * num_d;
                    const Index_type ell3 = (m + 3) * num_d;

                    real_t sum0 = lt_phidat[phi_base + m + 0];
                    real_t sum1 = lt_phidat[phi_base + m + 1];
                    real_t sum2 = lt_phidat[phi_base + m + 2];
                    real_t sum3 = lt_phidat[phi_base + m + 3];

                    Index_type dd = 0;

#if defined(__GNUC__) || defined(__clang__)
#pragma GCC ivdep
#endif
                    for (; dd + 3 < num_d; dd += 4) {
                        real_t p0 = lt_psidat[psi_base + dd + 0];
                        real_t p1 = lt_psidat[psi_base + dd + 1];
                        real_t p2 = lt_psidat[psi_base + dd + 2];
                        real_t p3 = lt_psidat[psi_base + dd + 3];

                        sum0 += lt_elldat[ell0 + dd + 0] * p0;
                        sum1 += lt_elldat[ell1 + dd + 0] * p0;
                        sum2 += lt_elldat[ell2 + dd + 0] * p0;
                        sum3 += lt_elldat[ell3 + dd + 0] * p0;

                        sum0 += lt_elldat[ell0 + dd + 1] * p1;
                        sum1 += lt_elldat[ell1 + dd + 1] * p1;
                        sum2 += lt_elldat[ell2 + dd + 1] * p1;
                        sum3 += lt_elldat[ell3 + dd + 1] * p1;

                        sum0 += lt_elldat[ell0 + dd + 2] * p2;
                        sum1 += lt_elldat[ell1 + dd + 2] * p2;
                        sum2 += lt_elldat[ell2 + dd + 2] * p2;
                        sum3 += lt_elldat[ell3 + dd + 2] * p2;

                        sum0 += lt_elldat[ell0 + dd + 3] * p3;
                        sum1 += lt_elldat[ell1 + dd + 3] * p3;
                        sum2 += lt_elldat[ell2 + dd + 3] * p3;
                        sum3 += lt_elldat[ell3 + dd + 3] * p3;
                    }

                    for (; dd < num_d; ++dd) {
                        real_t p = lt_psidat[psi_base + dd];
                        sum0 += lt_elldat[ell0 + dd] * p;
                        sum1 += lt_elldat[ell1 + dd] * p;
                        sum2 += lt_elldat[ell2 + dd] * p;
                        sum3 += lt_elldat[ell3 + dd] * p;
                    }

                    lt_phidat[phi_base + m + 0] = sum0;
                    lt_phidat[phi_base + m + 1] = sum1;
                    lt_phidat[phi_base + m + 2] = sum2;
                    lt_phidat[phi_base + m + 3] = sum3;
                }

                for (; m < num_m; ++m) {
                    const Index_type ell_base = m * num_d;
                    real_t sum = lt_phidat[phi_base + m];

                    Index_type dd = 0;

#if defined(__GNUC__) || defined(__clang__)
#pragma GCC ivdep
#endif
                    for (; dd + 3 < num_d; dd += 4) {
                        sum += lt_elldat[ell_base + dd]     * lt_psidat[psi_base + dd];
                        sum += lt_elldat[ell_base + dd + 1] * lt_psidat[psi_base + dd + 1];
                        sum += lt_elldat[ell_base + dd + 2] * lt_psidat[psi_base + dd + 2];
                        sum += lt_elldat[ell_base + dd + 3] * lt_psidat[psi_base + dd + 3];
                    }
                    for (; dd < num_d; ++dd) {
                        sum += lt_elldat[ell_base + dd] * lt_psidat[psi_base + dd];
                    }

                    lt_phidat[phi_base + m] = sum;
                }
            }
        }
        dummy(lt_phidat, NULL, NULL, NULL, NULL, 0.0f);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

