real_t apps_pressure(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t cls = 1.0f, p_cut = 1.0e-7f, pmin = 0.0f, eosvmax = 1.0e9f;
    const int niter = iterations / 4 + 1;

#if defined(__riscv_vector) && defined(__has_include)
#  if __has_include(<riscv_vector.h>)
#    include <riscv_vector.h>
    for (int nl = 0; nl < niter; nl++) {
        Index_type i = 0;

