            size_t vl = __riscv_vsetvl_e32m8((size_t)(APPS_N1D - i));
            vfloat32m8_t vcomp = __riscv_vle32_v_f32m8(&apps_compression[i], vl);
            vfloat32m8_t vbvc = __riscv_vfadd_vf_f32m8(vcomp, 1.0f, vl);
            vbvc = __riscv_vfmul_vf_f32m8(vbvc, cls, vl);
            __riscv_vse32_v_f32m8(&apps_bvc[i], vbvc, vl);
            i += (Index_type)vl;
        }

        i = 0;
        for (; i < APPS_N1D; ) {
            size_t vl = __riscv_vsetvl_e32m8((size_t)(APPS_N1D - i));

            vfloat32m8_t vbvc  = __riscv_vle32_v_f32m8(&apps_bvc[i], vl);
            vfloat32m8_t veold = __riscv_vle32_v_f32m8(&apps_e_old[i], vl);
            vfloat32m8_t vvnew = __riscv_vle32_v_f32m8(&apps_vnewc[i], vl);

            vfloat32m8_t vp = __riscv_vfmul_vv_f32m8(vbvc, veold, vl);
            vfloat32m8_t vzero = __riscv_vfmv_v_f_f32m8(0.0f, vl);
            vfloat32m8_t vabs = __riscv_vfabs_v_f32m8(vp, vl);

            vbool4_t m_abs_lt = __riscv_vmflt_vf_f32m8_b4(vabs, p_cut, vl);
            vp = __riscv_vmerge_vvm_f32m8(vp, vzero, m_abs_lt, vl);

            vbool4_t m_ge_eos = __riscv_vmfge_vf_f32m8_b4(vvnew, eosvmax, vl);
            vp = __riscv_vmerge_vvm_f32m8(vp, vzero, m_ge_eos, vl);

            vp = __riscv_vfmax_vf_f32m8(vp, pmin, vl);

            __riscv_vse32_v_f32m8(&apps_p_new[i], vp, vl);
            i += (Index_type)vl;
        }

        dummy(apps_p_new, apps_bvc, NULL, NULL, NULL, p_cut);
    }
#  else
    for (int nl = 0; nl < niter; nl++) {
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            apps_bvc[i] = cls * (apps_compression[i] + 1.0f);
        }
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            real_t p = apps_bvc[i] * apps_e_old[i];
            if (ABS(p) < p_cut)           p = 0.0f;
            if (apps_vnewc[i] >= eosvmax) p = 0.0f;
            if (p < pmin)                 p = pmin;
            apps_p_new[i] = p;
        }
        dummy(apps_p_new, apps_bvc, NULL, NULL, NULL, p_cut);
    }
#  endif
#else
    for (int nl = 0; nl < niter; nl++) {
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            apps_bvc[i] = cls * (apps_compression[i] + 1.0f);
