    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations; nl++) {
        Index_type i = 0;
        const real_t * __restrict x0 = apps_x0;
        const real_t * __restrict x1 = apps_x1;
        const real_t * __restrict x2 = apps_x2;
        const real_t * __restrict x3 = apps_x3;
        const real_t * __restrict x4 = apps_x4;
        const real_t * __restrict x5 = apps_x5;
        const real_t * __restrict x6 = apps_x6;
        const real_t * __restrict x7 = apps_x7;
        real_t * __restrict vol = apps_vol;

        for (; i + 3 < APPS_N1D; i += 4) {
            real_t s0 = x0[i]     + x1[i]     + x2[i]     + x3[i]     + x4[i]     + x5[i]     + x6[i]     + x7[i];
            real_t s1 = x0[i + 1] + x1[i + 1] + x2[i + 1] + x3[i + 1] + x4[i + 1] + x5[i + 1] + x6[i + 1] + x7[i + 1];
