            real_t s3 = x0[i + 3] + x1[i + 3] + x2[i + 3] + x3[i + 3] + x4[i + 3] + x5[i + 3] + x6[i + 3] + x7[i + 3];

            vol[i]     = (real_t)0.125f * s0;
            vol[i + 1] = (real_t)0.125f * s1;
            vol[i + 2] = (real_t)0.125f * s2;
            vol[i + 3] = (real_t)0.125f * s3;
