{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations; nl++) {
#if defined(__riscv_vector) && defined(__has_include)
#  if __has_include(<riscv_vector.h>)
#    include <riscv_vector.h>
        Index_type i = 0;
        for (; i < LEN_1D; ) {
            size_t vl = __riscv_vsetvl_e64m1((size_t)(LEN_1D - i));

            vfloat64m1_t va = __riscv_vle64_v_f64m1(&a[i], vl);
            vfloat64m1_t vb = __riscv_vle64_v_f64m1(&b[i], vl);
            vfloat64m1_t vc = __riscv_vle64_v_f64m1(&c[i], vl);

            vfloat64m1_t vb2 = __riscv_vfmul_vv_f64m1(vb, vb, vl);
            vfloat64m1_t vac = __riscv_vfmul_vv_f64m1(va, vc, vl);
            vfloat64m1_t v4ac = __riscv_vfmul_vf_f64m1(vac, 4.0, vl);
            vfloat64m1_t vs = __riscv_vfsub_vv_f64m1(vb2, v4ac, vl);

            vbool64_t mask = __riscv_vmfge_vf_f64m1_b64(vs, 0.0, vl);
            vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, vl);
            vfloat64m1_t vout1 = vzero;
            vfloat64m1_t vout2 = vzero;

            if (__riscv_vcpop_m_b64(mask, vl) != 0) {
                vfloat64m1_t vsqrt = __riscv_vfsqrt_v_f64m1(vs, vl);
                vfloat64m1_t vnegb = __riscv_vfneg_v_f64m1(vb, vl);
                vfloat64m1_t vden = __riscv_vfmul_vf_f64m1(va, 2.0, vl);
                vfloat64m1_t vnum2 = __riscv_vfadd_vv_f64m1(vnegb, vsqrt, vl);
                vfloat64m1_t vnum1 = __riscv_vfsub_vv_f64m1(vnegb, vsqrt, vl);

                vout2 = __riscv_vfdiv_vv_f64m1_m(mask, vzero, vnum2, vden, vl);
                vout1 = __riscv_vfdiv_vv_f64m1_m(mask, vzero, vnum1, vden, vl);
            }

            __riscv_vse64_v_f64m1(&out2[i], vout2, vl);
            __riscv_vse64_v_f64m1(&out1[i], vout1, vl);
            i += (Index_type)vl;
        }
#  else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            real_t bi = b[i];
            real_t ai = a[i];
            real_t ci = c[i];
            real_t s = bi * bi - 4.0 * ai * ci;
            if (s >= 0) {
                s = sqrt(s);
                real_t denom = 2.0 * ai;
                out2[i] = (-bi + s) / denom;
                out1[i] = (-bi - s) / denom;
            } else {
                out2[i] = 0.0;
                out1[i] = 0.0;
            }
        }
#  endif
#else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            real_t bi = b[i];
            real_t ai = a[i];
            real_t ci = c[i];
            real_t s = bi * bi - 4.0 * ai * ci;
