    gettimeofday(&func_args->t1, NULL);

    Index_type len = 0;
    const int outer = iterations / 8 + 1;

    for (int nl = 0; nl < outer; nl++) {
        Index_type count = 0;

#if defined(__riscv_vector) && defined(__has_include)
#  if __has_include(<riscv_vector.h>)
#    include <riscv_vector.h>
        Index_type i = 0;
        const real_t zero = (real_t)0.0;

        for (; i < LEN_1D; ) {
            size_t vl = __riscv_vsetvl_e64m1((size_t)(LEN_1D - i));
            vfloat64m1_t vx = __riscv_vle64_v_f64m1(&x[i], vl);
            vbool64_t mask = __riscv_vmflt_vf_f64m1_b64(vx, zero, vl);
            size_t nneg = __riscv_vcpop_m_b64(mask, vl);

            if (nneg) {
                vuint64m1_t vidx = __riscv_vid_v_u64m1(vl);
                vidx = __riscv_vadd_vx_u64m1(vidx, (uint64_t)i, vl);
                __riscv_vse64_v_u64m1_m(mask, (uint64_t *)&idx_list[count], vidx, vl);
                count += (Index_type)nneg;
            }

            i += (Index_type)vl;
        }
#  else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            if (x[i] < 0.0) {
                idx_list[count++] = i;
            }
        }
#  endif
#else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            if (x[i] < 0.0) {
                idx_list[count++] = i;
            }
        }
#endif

        len = count;
        dummy(NULL, NULL, NULL, NULL, NULL, (real_t)count);
    }

    idx_list[0] = len;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

