        const real_t * __restrict__ px = x;
        Index_type * __restrict__ pic = idx_counts;
        Index_type * __restrict__ pil = idx_list;

        Index_type i = 0;
        for (; i + 3 < LEN_1D; i += 4) {
            real_t x0 = px[i];
            real_t x1 = px[i + 1];
            real_t x2 = px[i + 2];
            real_t x3 = px[i + 3];
            pic[i]     = (x0 < 0.0) ? 1 : 0;
            pic[i + 1] = (x1 < 0.0) ? 1 : 0;
            pic[i + 2] = (x2 < 0.0) ? 1 : 0;
            pic[i + 3] = (x3 < 0.0) ? 1 : 0;
        }
        for (; i < LEN_1D; ++i) {
            pic[i] = (px[i] < 0.0) ? 1 : 0;
        }

        Index_type count = 0;
        for (i = 0; i <= LEN_1D; ++i) {
            Index_type inc = pic[i];
            pic[i] = count;
            count += inc;
        }

        for (i = 0; i < LEN_1D; ++i) {
            if (pic[i] != pic[i + 1]) {
                pil[pic[i]] = i;
            }
        }

        len = pic[LEN_1D];
        dummy(NULL, NULL, NULL, NULL, NULL, (real_t)count);
    }

    idx_list[0] = len;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
