real_t basic_pi_atomic(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    const real_t dx = (real_t)1.0 / (real_t)LEN_1D;
    const real_t half = (real_t)0.5;
    const real_t four = (real_t)4.0;
    real_t pi_acc = (real_t)0.0;

    for (int nl = 0; nl < iterations; ++nl) {
        real_t pi = (real_t)0.0;

#if defined(__riscv_vector) && defined(RUN_DOUBLE)
        {
            Index_type i = 0;
            while (i < LEN_1D) {
                size_t vl = __riscv_vsetvl_e64m2((size_t)(LEN_1D - i));
                vuint64m2_t vid = __riscv_vid_v_u64m2(vl);
                vfloat64m2_t vfi = __riscv_vfcvt_f_xu_v_f64m2(vid, vl);
                vfi = __riscv_vfadd_vf_f64m2(vfi, (real_t)i, vl);
                vfloat64m2_t vx = __riscv_vfmadd_vf_f64m2(vfi, dx, __riscv_vfmv_v_f_f64m2(half * dx, vl), vl);
                vfloat64m2_t vden = __riscv_vfmacc_vf_f64m2(__riscv_vfmv_v_f_f64m2((real_t)1.0, vl), (real_t)1.0, __riscv_vfmul_vv_f64m2(vx, vx, vl), vl);
                vfloat64m2_t vterm = __riscv_vfdiv_vf_f64m2(vden, dx, vl);
                vfloat64m1_t vsum = __riscv_vfredusum_vs_f64m2_f64m1(
                    vterm,
                    __riscv_vfmv_v_f_f64m1((real_t)0.0, 1),
                    __riscv_vfmv_v_f_f64m1((real_t)0.0, 1),
                    vl);
                pi += __riscv_vfmv_f_s_f64m1_f64(vsum);
                i += (Index_type)vl;
            }
        }
#elif defined(__riscv_vector) && defined(RUN_FLOAT)
        {
            Index_type i = 0;
            while (i < LEN_1D) {
                size_t vl = __riscv_vsetvl_e32m4((size_t)(LEN_1D - i));
                vuint32m4_t vid = __riscv_vid_v_u32m4(vl);
                vfloat32m4_t vfi = __riscv_vfcvt_f_xu_v_f32m4(vid, vl);
                vfi = __riscv_vfadd_vf_f32m4(vfi, (real_t)i, vl);
                vfloat32m4_t vx = __riscv_vfmadd_vf_f32m4(vfi, dx, __riscv_vfmv_v_f_f32m4(half * dx, vl), vl);
                vfloat32m4_t vden = __riscv_vfmacc_vf_f32m4(__riscv_vfmv_v_f_f32m4((real_t)1.0, vl), (real_t)1.0, __riscv_vfmul_vv_f32m4(vx, vx, vl), vl);
                vfloat32m4_t vterm = __riscv_vfdiv_vf_f32m4(vden, dx, vl);
                vfloat32m1_t vsum = __riscv_vfredusum_vs_f32m4_f32m1(
                    vterm,
                    __riscv_vfmv_v_f_f32m1((real_t)0.0, 1),
                    __riscv_vfmv_v_f_f32m1((real_t)0.0, 1),
                    vl);
                pi += __riscv_vfmv_f_s_f32m1_f32(vsum);
                i += (Index_type)vl;
            }
        }
#else
        for (Index_type i = 0; i < LEN_1D; ++i) {
            real_t xv = ((real_t)i + half) * dx;
            pi += dx / ((real_t)1.0 + xv * xv);
        }
#endif

        pi_acc += pi * four;
        dummy(NULL, NULL, NULL, NULL, NULL, pi);
    }

    x[0] = pi_acc;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

