        real_t xs = 0, ys = 0;
        real_t xn = x[0], xx_ = x[0], yn = y[0], yx = y[0];

        Index_type i = 0;

#if defined(__GNUC__) || defined(__clang__)
#pragma GCC ivdep
#endif
        for (; i + 3 < LEN_1D; i += 4) {
            real_t x0 = x[i];
            real_t y0 = y[i];
            real_t x1 = x[i + 1];
            real_t y1 = y[i + 1];
            real_t x2 = x[i + 2];
            real_t y2 = y[i + 2];
            real_t x3 = x[i + 3];
            real_t y3 = y[i + 3];

            xs += x0 + x1 + x2 + x3;
            ys += y0 + y1 + y2 + y3;

            if (x0 < xn) xn = x0;
            if (x0 > xx_) xx_ = x0;
            if (y0 < yn) yn = y0;
            if (y0 > yx) yx = y0;

            if (x1 < xn) xn = x1;
            if (x1 > xx_) xx_ = x1;
            if (y1 < yn) yn = y1;
            if (y1 > yx) yx = y1;

