            if (x2 > xx_) xx_ = x2;
            if (y2 < yn) yn = y2;
            if (y2 > yx) yx = y2;

            if (x3 < xn) xn = x3;
            if (x3 > xx_) xx_ = x3;
            if (y3 < yn) yn = y3;
            if (y3 > yx) yx = y3;
        }

        for (; i < LEN_1D; ++i) {
            real_t xi = x[i];
            real_t yi = y[i];
            xs += xi;
            ys += yi;
            if (xi < xn) xn = xi;
            if (xi > xx_) xx_ = xi;
            if (yi < yn) yn = yi;
            if (yi > yx) yx = yi;
        }

        xsum = xs; ysum = ys; xmin = xn; xmax = xx_; ymin = yn; ymax = yx;
        dummy(x, y, NULL, NULL, NULL, xs);
    }

    z[0] = xsum; z[1] = xmin; z[2] = xmax;
    z[3] = ysum; z[4] = ymin; z[5] = ymax;

    gettimeofday(&func_args->t2, NULL);
