                real_t zq_k1_jm1_3 = zq_k1[j + 2];
                real_t zp_k_jm1_3  = zp_k[j + 2];
                real_t zq_k_jm1_3  = zq_k[j + 2];
                real_t zr_k_j_3    = zr_k[j + 3];
