                                za_k[j - 1] * (zzj0 - zz_k[j - 1]) -
                                zb_k[j]     * (zzj0 - zz_km1[j]) +
                                zb_k1[j]    * (zzj0 - zz_k1[j]));
                zv_k[j] += s * (za_k[j]     * (zrj0 - zr_k[j + 1]) -
                                za_k[j - 1] * (zrj0 - zr_k[j - 1]) -
                                zb_k[j]     * (zrj0 - zr_km1[j]) +
                                zb_k1[j]    * (zrj0 - zr_k1[j]));

                real_t zzj1 = zz_k[j + 1];
                real_t zrj1 = zr_k[j + 1];
                zu_k[j + 1] += s * (za_k[j + 1] * (zzj1 - zz_k[j + 2]) -
                                    za_k[j]     * (zzj1 - zz_k[j]) -
                                    zb_k[j + 1] * (zzj1 - zz_km1[j + 1]) +
                                    zb_k1[j + 1]* (zzj1 - zz_k1[j + 1]));
                zv_k[j + 1] += s * (za_k[j + 1] * (zrj1 - zr_k[j + 2]) -
                                    za_k[j]     * (zrj1 - zr_k[j]) -
                                    zb_k[j + 1] * (zrj1 - zr_km1[j + 1]) +
                                    zb_k1[j + 1]* (zrj1 - zr_k1[j + 1]));

                real_t zzj2 = zz_k[j + 2];
                real_t zrj2 = zr_k[j + 2];
                zu_k[j + 2] += s * (za_k[j + 2] * (zzj2 - zz_k[j + 3]) -
                                    za_k[j + 1] * (zzj2 - zz_k[j + 1]) -
                                    zb_k[j + 2] * (zzj2 - zz_km1[j + 2]) +
                                    zb_k1[j + 2]* (zzj2 - zz_k1[j + 2]));
                zv_k[j + 2] += s * (za_k[j + 2] * (zrj2 - zr_k[j + 3]) -
                                    za_k[j + 1] * (zrj2 - zr_k[j + 1]) -
                                    zb_k[j + 2] * (zrj2 - zr_km1[j + 2]) +
                                    zb_k1[j + 2]* (zrj2 - zr_k1[j + 2]));

                real_t zzj3 = zz_k[j + 3];
                real_t zrj3 = zr_k[j + 3];
                zu_k[j + 3] += s * (za_k[j + 3] * (zzj3 - zz_k[j + 4]) -
                                    za_k[j + 2] * (zzj3 - zz_k[j + 2]) -
                                    zb_k[j + 3] * (zzj3 - zz_km1[j + 3]) +
                                    zb_k1[j + 3]* (zzj3 - zz_k1[j + 3]));
                zv_k[j + 3] += s * (za_k[j + 3] * (zrj3 - zr_k[j + 4]) -
                                    za_k[j + 2] * (zrj3 - zr_k[j + 2]) -
                                    zb_k[j + 3] * (zrj3 - zr_km1[j + 3]) +
                                    zb_k1[j + 3]* (zrj3 - zr_k1[j + 3]));
            }

            for (; j < j_end; ++j) {
                real_t zzj = zz_k[j];
                real_t zrj = zr_k[j];

                zu_k[j] += s * (za_k[j]   * (zzj - zz_k[j + 1]) -
                                za_k[j - 1] * (zzj - zz_k[j - 1]) -
                                zb_k[j]   * (zzj - zz_km1[j]) +
                                zb_k1[j]  * (zzj - zz_k1[j]));

                zv_k[j] += s * (za_k[j]   * (zrj - zr_k[j + 1]) -
                                za_k[j - 1] * (zrj - zr_k[j - 1]) -
                                zb_k[j]   * (zrj - zr_km1[j]) +
