#if defined(__riscv_vector) && defined(__has_include)
#  if __has_include(<riscv_vector.h>)
#    include <riscv_vector.h>
        Index_type i = 0;
        for (; i < LEN_1D; ) {
            size_t vl = __riscv_vsetvl_e64m1((size_t)(LEN_1D - i));

            vfloat64m1_t v12 = __riscv_vle64_v_f64m1(&p12[i], vl);
            vfloat64m1_t v11 = __riscv_vle64_v_f64m1(&p11[i], vl);
            vfloat64m1_t v10 = __riscv_vle64_v_f64m1(&p10[i], vl);
