            vfloat64m1_t v2  = __riscv_vle64_v_f64m1(&p2[i],  vl);

            vfloat64m1_t acc = __riscv_vfmul_vf_f64m1(v12, dm28, vl);
            acc = __riscv_vfmacc_vf_f64m1(acc, dm27, v11, vl);
            acc = __riscv_vfmacc_vf_f64m1(acc, dm26, v10, vl);
            acc = __riscv_vfmacc_vf_f64m1(acc, dm25, v9,  vl);
            acc = __riscv_vfmacc_vf_f64m1(acc, dm24, v8,  vl);
            acc = __riscv_vfmacc_vf_f64m1(acc, dm23, v7,  vl);
            acc = __riscv_vfmacc_vf_f64m1(acc, dm22, v6,  vl);

            vfloat64m1_t s45 = __riscv_vfadd_vv_f64m1(v4, v5, vl);
            acc = __riscv_vfmacc_vf_f64m1(acc, c0, s45, vl);
            acc = __riscv_vfadd_vv_f64m1(acc, v2, vl);

            __riscv_vse64_v_f64m1(&base[i], acc, vl);
