        for (Index_type i = 0; i < LEN_1D; ++i) {
            base[i] = dm28*p12[i] + dm27*p11[i] +
                      dm26*p10[i] + dm25*p9[i]  +
                      dm24*p8[i]  + dm23*p7[i]  +
                      dm22*p6[i]  +
                      c0*(p4[i] + p5[i]) +
                      p2[i];
